import { Composio } from "@composio/core";
import { OpenAIProvider } from "@composio/openai";

// Read API keys from environment
const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const COMPOSIO_API_KEY = process.env.COMPOSIO_API_KEY;

// Configuration
const USER_ID = "zealt-user01";
const TRIAL_ID_PATH = "/logs/trial_id";

async function runAgentLoop(
  openai: OpenAI,
  composio: Composio<OpenAIProvider>,
  userId: string,
  tools: OpenAI.Responses.Tool[],
  task: string,
  maxIter: number = 15
): Promise<string> {
  const input: OpenAI.Responses.ResponseInputItem[] = [
    { role: "user", content: task },
  ];

  let iteration = 0;

  while (iteration < maxIter) {
    iteration++;
    console.log(`\n  [Agent] Iteration ${iteration}...`);

    const response = await openai.responses.create({
      model: "gpt-4o-mini",
      input,
      tools,
    });

    console.log(`  [Agent] Status: ${response.status}`);

    // Collect text output and check if done
    const textItems = response.output.filter((o) => o.type === "message");
    const toolCalls = response.output.filter(
      (o) => o.type === "function_call"
    );

    if (toolCalls.length === 0) {
      // No more tool calls - extract final text
      const finalText = textItems
        .flatMap((m: any) =>
          (m.content || [])
            .filter((c: any) => c.type === "output_text")
            .map((c: any) => c.text)
        )
        .join("\n");
      console.log(`  [Agent] Done after ${iteration} iterations`);
      return finalText || "Task completed.";
    }

    // Handle tool calls
    const toolOutputs = await composio.provider.handleResponse(
      userId,
      response
    );
    console.log(`  [Agent] Executed ${toolCalls.length} tool(s)`);

    // Add all output items to input for next iteration
    for (const outputItem of response.output) {
      input.push(outputItem as OpenAI.Responses.ResponseInputItem);
    }
    for (const toolOutput of toolOutputs) {
      input.push(toolOutput);
    }
  }

  return "Max iterations reached.";
}

async function main() {
  // Read trial_id
  const trialId = fs.readFileSync(TRIAL_ID_PATH, "utf-8").trim();
  const slackChannel = `summary-${trialId}`;

  console.log(`Trial ID: ${trialId}`);
  console.log(`Slack channel: ${slackChannel}`);

  // Initialize OpenAI client
  const openai = new OpenAI({ apiKey: OPENAI_API_KEY });

  // Initialize Composio with OpenAI provider
  const composio = new Composio({
    apiKey: COMPOSIO_API_KEY,
    provider: new OpenAIProvider(),
  });

  // Create a tool router session for the user
  console.log("\nCreating Composio session...");
  const session = await composio.create(USER_ID, {
    manageConnections: true,
  });
  console.log(`Session ID: ${session.sessionId}`);

  // Get session tools (meta tools for tool routing)
  const sessionTools =
    (await session.tools()) as OpenAI.Responses.Tool[];
  console.log(
    `Session tools: ${sessionTools
      .map((t: any) => t.function?.name)
      .filter(Boolean)
      .join(", ")}`
  );

  // Step 1: Use the agent to fetch last 5 Gmail emails via tool router
  console.log("\n--- Step 1: Fetching last 5 Gmail emails ---");
  const gmailTask = `You are a helpful assistant. Your task is to fetch the last 5 messages from Gmail for this user.

Instructions:
1. First call COMPOSIO_SEARCH_TOOLS with queries for "fetch last 5 messages from Gmail inbox" to discover the right tool and get the execution plan. Use session: {generate_id: true}.
2. Check the connection info in the response. If Gmail is not connected, use COMPOSIO_MANAGE_CONNECTIONS to initiate the Gmail connection.
3. Once connected, use COMPOSIO_MULTI_EXECUTE_TOOL to execute the Gmail list messages tool to get the last 5 emails.
4. Return the subjects and senders of the 5 emails.`;

  const gmailData = await runAgentLoop(
    openai,
    composio,
    USER_ID,
    sessionTools,
    gmailTask,
    15
  );
  console.log("\nGmail data:", gmailData.substring(0, 1000));

  // Step 2: Create a summary using OpenAI
  console.log("\n--- Step 2: Creating email summary ---");
  const summaryResponse = await openai.responses.create({
    model: "gpt-4o-mini",
    input: [
      {
        role: "user",
        content: `Based on the following Gmail data, create a concise summary of the last 5 emails:\n\n${gmailData}\n\nProvide a brief, readable summary with key information from each email (subject, sender, key points).`,
      },
    ],
  });

  const summary =
    (summaryResponse.output_text ?? "") ||
    `Email Summary:\n${gmailData}`;

  console.log("\nSummary:", summary);

  // Step 3: Post summary to Slack
  console.log(
    `\n--- Step 3: Posting to Slack channel

